const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a bounding box for Southern California
  const southCalifornia = ee.Geometry.BBox(-120.5, 32.5, -114.0, 35.0); // Approx. Southern California

  const startDate2003 = '2003-04-14';
  const endDate2003 = '2003-04-22'; // Use one day after to ensure full inclusion of the 21st
  const startDate2004 = '2004-04-14';
  const endDate2004 = '2004-04-22';

  // MODIS Land Surface Temperature and Emissivity 8-Day Global 1km
  const collectionId = 'MODIS/061/MOD11A2'; // Use MOD11A2 for 8-day composites

  // Function to get and process LST data for a given year
  const getLST = async (year, startDate, endDate) => {
    let collection = ee.ImageCollection(collectionId)
      .filterBounds(southCalifornia)
      .filterDate(startDate, endDate)
      .select('LST_Day_1km'); // Select Day LST band

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No images found for ${year}.`);
      return null;
    }

    // Since MOD11A2 is an 8-day composite, we expect at most one image covering the 7-day period.
    // If multiple images are found, take the median.
    let image = collection.median();

    // LST_Day_1km values are in Kelvin * 0.02. Convert to Celsius.
    // LST in Kelvin = LST_Day_1km * 0.02
    // LST in Celsius = (LST_Day_1km * 0.02) - 273.15
    image = image.multiply(0.02).subtract(273.15).rename('LST_Celsius');

    // Mask out invalid values (e.g., water, clouds, fill values which are typically 0 or very low after scaling)
    // The original data range is 7500-65535, so 0.02 * 7500 = 150K. 0.02 * 65535 = 1310K.
    // After conversion to Celsius, LST should be within a reasonable range for land (e.g., > -50 and < 70).
    // Let's mask values outside this range.
    image = image.updateMask(image.gt(-50).and(image.lt(70)));

    // Calculate mean LST for the region
    const stats = await image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: southCalifornia,
      scale: 1000, // MODIS resolution is 1km
      maxPixels: 1e9,
    }).getInfo();

    const meanLST = stats ? stats['LST_Celsius'] : null;
    const pixelCount = stats ? stats['LST_Celsius_count'] : 0;

    if (pixelCount === 0) {
      console.log(`No valid pixels after processing for ${year}.`);
      return { meanLST: null, pixelCount: 0 };
    }

    return { meanLST: meanLST, pixelCount: pixelCount };
  };

  console.log("Analyzing LST for Southern California...");

  // 2. Data Acquisition & Processing for 2003
  const result2003 = await getLST(2003, startDate2003, endDate2003);
  if (result2003 === null) { console.log("C1"); return; }
  const { meanLST: lst2003, pixelCount: pixels2003 } = result2003;
  console.log(`2003 LST (April 14-21): ${lst2003 !== null ? lst2003.toFixed(2) + ' °C' : 'N/A'}, Pixels: ${pixels2003}`);
  if (pixels2003 === 0) { console.log("C2"); return; }
  if (lst2003 === null || isNaN(lst2003)) { console.log("C3"); return; }


  // 3. Data Acquisition & Processing for 2004
  const result2004 = await getLST(2004, startDate2004, endDate2004);
  if (result2004 === null) { console.log("C1"); return; }
  const { meanLST: lst2004, pixelCount: pixels2004 } = result2004;
  console.log(`2004 LST (April 14-21): ${lst2004 !== null ? lst2004.toFixed(2) + ' °C' : 'N/A'}, Pixels: ${pixels2004}`);
  if (pixels2004 === 0) { console.log("C2"); return; }
  if (lst2004 === null || isNaN(lst2004)) { console.log("C3"); return; }

  // 4. Comparison and Final Answer
  if (lst2003 !== null && lst2004 !== null) {
    if (lst2004 > lst2003) {
      console.log("A"); // Yes, LST increased
    } else {
      console.log("B"); // No, LST did not increase (it decreased or stayed the same)
    }
  } else {
    // This case should ideally be caught by C3 checks above.
    console.log("C3"); // Calculation failure if any LST value is null/NaN here
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
